// ---- Register map: adapt to your device ---------------------------------
const DEVICE = env.get('DEVICE_NAME') || 'plc1';
const MEASUREMENT = 'plc_process';
const WORDS = 4;                      // must match 'quantity' in the Modbus Read node
const MAP = [
  { name: 'temperature_c', offset: 0, type: 'int16',  scale: 0.1,  min: -50, max: 500 },
  { name: 'pressure_bar',  offset: 1, type: 'uint16', scale: 0.01, min: 0,   max: 100 },
  // 32-bit counter, high word first (big-endian word order)
  { name: 'energy_wh',     offset: 2, type: 'uint32', scale: 1,    min: 0,   max: 4294967295 }
];
// --------------------------------------------------------------------------
const w = msg.payload;
if (!Array.isArray(w) || w.length < WORDS) {
  node.error('Unexpected Modbus payload, expected ' + WORDS + ' words', msg);
  return null;
}
const s16 = v => (v > 32767 ? v - 65536 : v);
const fields = {};
const rejected = [];
for (const m of MAP) {
  let raw;
  switch (m.type) {
    case 'int16':  raw = s16(w[m.offset]); break;
    case 'uint16': raw = w[m.offset]; break;
    case 'uint32': raw = w[m.offset] * 65536 + w[m.offset + 1]; break;
    default: raw = NaN;
  }
  const val = raw * m.scale;
  if (!Number.isFinite(val) || val < m.min || val > m.max) {
    rejected.push(m.name + '=' + val);
    continue;                           // drop the bad signal, keep the good ones
  }
  fields[m.name] = Math.round(val * 10000) / 10000;
}
if (rejected.length) {
  flow.set('bad_count', (flow.get('bad_count') || 0) + 1);
  node.warn('Out-of-range/invalid values dropped: ' + rejected.join(', '));
}
if (Object.keys(fields).length === 0) { return null; }
flow.set('ok_count', (flow.get('ok_count') || 0) + 1);

// New message object: don't forward Modbus internals to the DB node.
return {
  payload: [{
    measurement: MEASUREMENT,
    tags: { device: DEVICE, source: 'modbus_tcp' },
    fields: fields,
    timestamp: new Date()
  }]
};

const DEVICE = env.get('DEVICE_NAME') || 'plc1';
const err = msg.error || {};
const src = (err.source && (err.source.name || err.source.type)) || 'unknown';
flow.set('err_count', (flow.get('err_count') || 0) + 1);
return {
  payload: [{
    measurement: 'collector_events',
    tags: { device: DEVICE, level: 'error', source: String(src) },
    fields: { message: String(err.message || 'unknown error').slice(0, 200), count: 1 },
    timestamp: new Date()
  }]
};

const DEVICE = env.get('DEVICE_NAME') || 'plc1';
return {
  payload: [{
    measurement: 'collector_heartbeat',
    tags: { device: DEVICE },
    fields: {
      ok_polls: flow.get('ok_count') || 0,
      bad_polls: flow.get('bad_count') || 0,
      errors: flow.get('err_count') || 0
    },
    timestamp: new Date()
  }]
};
